package com.bobfull.chat.presentation.controller;
import com.bobfull.chat.presentation.dto.*; import com.bobfull.chat.application.service.ChatRoomMemberReportService; import com.bobfull.common.response.ApiResponse; import com.bobfull.auth.application.model.AuthMember; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/chat-rooms/{chatRoomId}/members/{reportedMemberId}/reports") public class ChatRoomMemberReportController { private final ChatRoomMemberReportService service; public ChatRoomMemberReportController(ChatRoomMemberReportService service){this.service=service;} @PostMapping public ApiResponse<ChatRoomMemberReportResponse> create(@AuthenticationPrincipal AuthMember member,@PathVariable Long chatRoomId,@PathVariable Long reportedMemberId,@Valid @RequestBody ChatRoomMemberReportCreateRequest request){return ApiResponse.success(service.create(member.id(),chatRoomId,reportedMemberId,request));} }
